prolog:
#Region }IDE.Backup
# ====================================================================================================
# }IDE.Backup -- save the data, then archive the data folder into the sibling 'backup' folder.
# One generic core process for any TM1 model, written and maintained here.
#
# WHAT IT DOES
#   1. SaveDataAll                       writes every changed cube value to disk (TM1)
#   2. picks the next free archive name  TM1Backup_1, _2, _3 ... in the backup folder
#   3. runs Windows' own tar.exe          no generated script: TM1's ASCIIOUTPUT is buffered until
#                                         the process ends, so a file written here is not on disk yet
#                                         when ExecuteCommand runs (learned the hard way, 26 Nov)
#   4. checks the archive exists         no archive -> this process FAILS, so a deploy that asked
#                                         for a backup stops instead of sending
#   5. keeps the last pKeep archives     older ones are deleted by this process
#
# WHERE THE ARCHIVES GO
#   Beside the data folder, never inside it -- a zip written into 'data' would swallow itself:
#     <server>\data      the model (this is what is archived)
#     <server>\backup    TM1Backup_<n>.zip      (pFormat=copy: TM1Backup_<n>\)
#
# WHO RUNS IT
#   The IDE (Deploy -> Protection sets it as the target's backup process, so every deploy runs it
#   first) or a person from the same screen. Hidden process (leading }), not model content.
#
# SOURCE  ti-processes/backup/process.json in the TM1 IDE repo. The server copy is the runtime copy;
#         the IDE creates it on demand, exactly like }IDE.SaveDataAll.
# ====================================================================================================
#EndRegion
cThis   = GetProcessName();
cBackup = pTargetDir;
IF(cBackup @= ''); cBackup = '..\backup'; ENDIF;
IF(pFormat @= ''); pFormat = 'zip'; ENDIF;
nKeep = pKeep;
IF(nKeep < 1); nKeep = 1; ENDIF;
IF(nKeep > 100); nKeep = 100; ENDIF;
cRoot = cBackup | '\TM1Backup_';

# 1. The model on disk, before anything is archived.
SaveDataAll;

# 2. The folder beside the data folder, created if this is the first backup.
ExecuteCommand('cmd /c if not exist "' | cBackup | '" mkdir "' | cBackup | '"', 1);

# 3. Next free number. A numbered name needs no date formatting, and the file's own timestamp
#    still shows when it was taken.
n = 1;
WHILE(FILEEXISTS(cRoot | NumberToString(n) | '.zip') = 1 % FILEEXISTS(cRoot | NumberToString(n)) = 1);
  n = n + 1;
END;

# 4. Archive. Windows 10+ ships tar.exe (libarchive); it writes the zip in one call.
IF(pFormat @= 'copy');
  ExecuteCommand('cmd /c xcopy ".\*" "' | cRoot | NumberToString(n) | '" /i /c /y /e /q', 1);
  IF(FILEEXISTS(cRoot | NumberToString(n)) = 0);
    ItemReject(cThis | ': backup FAILED -- folder copy not created at ' | cRoot | NumberToString(n));
    ProcessError;
  ENDIF;
ELSE;
  ExecuteCommand('cmd /c tar.exe -a -c -f "' | cRoot | NumberToString(n) | '.zip" -C . .', 1);
  IF(FILEEXISTS(cRoot | NumberToString(n) | '.zip') = 0);
    ItemReject(cThis | ': backup FAILED -- tar.exe did not create ' | cRoot | NumberToString(n) | '.zip');
    ProcessError;
  ENDIF;
ENDIF;

# 5. Retention by number: keep the newest nKeep, delete everything older.
m = n - nKeep;
IF(m > 0);
  k = 1;
  WHILE(k <= m);
    IF(pFormat @= 'copy');
      ExecuteCommand('cmd /c rmdir /s /q "' | cRoot | NumberToString(k) | '"', 1);
    ELSE;
      ExecuteCommand('cmd /c del /q "' | cRoot | NumberToString(k) | '.zip"', 1);
    ENDIF;
    k = k + 1;
  END;
ENDIF;

LogOutput('INFO', cThis | ': backup ' | NumberToString(n) | ' written for ' | cBackup | ' (kept ' | NumberToString(nKeep) | ')');
